// Gen V (Black, White, Black 2, White 2) PK5 legality through Legality::analyzePk5.
//
// Fixture records are synthetic: PKHeX.Core (commit pinned in Gen5LegalityData.h)
// built each one from its own encounter templates (Gen V encounters, in-game trades
// in every language, PGF cards, Gen III/IV encounters converted the way Pal Park and
// Poke Transfer do, grown copies) for test trainers, then the differential oracle
// (tools/pkhex_gen5_diff, `generate SEED 3|4`) applied a single-field mutation.
// Expected verdict classes:
//   Valid    PKHeX VALID and "No problems found" here: no Invalid, no Warning and
//            every coverage area Complete.
//   Invalid  PKHeX INVALID and Invalid here.
//   Unknown  this analyzer cannot decide (a Colosseum / XD original encounter, an
//            unknown card, text outside the modelled domain, a PKHeX quirk or "fishy"
//            result) and must report Warning/Incomplete, never Invalid, whatever PKHeX says.
// Then rule edits of fixture records, malformed sizes, encryption round trips, input
// immutability and a deterministic fuzz pass over random and mutated records (run
// under ASan/UBSan by host-sanitize).
#include <algorithm>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <string>
#include <vector>

#include "Encryption/Encryption5.h"
#include "Legality/Gen5Legality.h"
#include "legality_gen5_test_helpers.h"

